<div class="admin-page-head"><div><span class="eyebrow">فروش و کمپین</span><h1>کدهای تخفیف</h1><p>حداقل خرید، سقف تخفیف، زمان و محدودیت استفاده</p></div><?= CHtml::link('+ کد جدید',array('adminCoupon/create'),array('class'=>'btn btn-primary','data-pjax'=>'1')) ?></div>
<section class="panel table-wrap"><table class="data-table"><thead><tr><th>کد</th><th>تخفیف</th><th>حداقل خرید</th><th>مصرف / ظرفیت</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($coupons as $c): ?><tr><td dir="ltr"><strong><?= CHtml::encode($c->code) ?></strong></td><td><?= $c->kind==='percent'?number_format($c->amount).'%':Money::format($c->amount) ?></td><td><?= Money::format($c->minimum_total) ?></td><td><?= $c->used_count ?> / <?= $c->usage_limit?:'نامحدود' ?></td><td><?= $c->is_active?'فعال':'غیرفعال' ?></td><td><?= CHtml::link('ویرایش',array('adminCoupon/update','id'=>$c->id),array('class'=>'table-action','data-pjax'=>'1')) ?><?= CHtml::beginForm(array('adminCoupon/toggle','id'=>$c->id),'post',array('class'=>'inline-form')) ?><?= CHtml::submitButton($c->is_active?'غیرفعال':'فعال',array('class'=>'btn btn-outline btn-sm')) ?><?= CHtml::endForm() ?></td></tr><?php endforeach; ?><?php if(!$coupons): ?><tr><td colspan="6">هنوز کد تخفیفی ساخته نشده است.</td></tr><?php endif; ?></tbody></table></section>
